<script>$(function(){const csrf=$('meta[name=csrf-token]').attr('content');const Q='chist-attendance-queue';function queue(){try{return JSON.parse(localStorage.getItem(Q)||'[]')}catch(e){return[]}}function badge(){let n=queue().length;window.dispatchEvent(new CustomEvent('chist-queue',{detail:n}))}function enqueue(url,data){let q=queue();q.push({url,data});localStorage.setItem(Q,JSON.stringify(q));badge();state('Офлайн: сохранено на телефоне ⏳')}async function flush(){if(!navigator.onLine)return;let q=queue(),left=[];for(let x of q){try{let body=new URLSearchParams(x.data);let r=await fetch(x.url,{method:'POST',headers:{'X-CSRF-TOKEN':csrf,'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body});if(!r.ok)left.push(x)}catch(e){left.push(x)}}localStorage.setItem(Q,JSON.stringify(left));badge();if(q.length&&!left.length)state('Офлайн-отметки синхронизированы ✓')}window.addEventListener('online',flush);badge();flush();function state(t){$('#saveStatus').text(t)}$('#lessonGradeType').on('change',function(){let el=$(this),s=$('#gradeTypeSave');s.text('сохранение…');$.post('{{route('journal.lesson.grade-type',$l->id)}}',{_token:csrf,grade_type:el.val()}).done(()=>{s.text('сохранено ✓');setTimeout(()=>s.text(''),1200)}).fail(()=>s.text('ошибка сохранения'))});$('#allPresent').on('click',function(){if(!confirm('Отметить всех студентов присутствующими?'))return;state('Сохраняю перекличку…');$.post('{{route('journal.attendance.all',$l->id)}}',{_token:csrf}).done(()=>{state('Все присутствующие сохранены ✓');$('.attendance button[data-value=present]').each(function(){let b=$(this);b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary')})}).fail(()=>state('Ошибка сохранения'))});$('.attendance button').on('click',function(){let b=$(this),row=b.closest('.student-row');state('Сохраняю…');let data={_token:csrf,student_id:row.data('student'),status:b.data('value')};if(!navigator.onLine){enqueue('{{route('journal.attendance',$l->id)}}',data);b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary');return}$.post('{{route('journal.attendance',$l->id)}}',data).done(()=>{b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary');state('Сохранено ✓')}).fail(()=>{enqueue('{{route('journal.attendance',$l->id)}}',data);b.siblings().removeClass('btn-primary').addClass('btn-outline-secondary');b.removeClass('btn-outline-secondary').addClass('btn-primary')})});$('.grades button').on('click',function(){let b=$(this),row=b.closest('.student-row');state('Сохраняю оценку…');$.post('{{route('journal.grade',$l->id)}}',{_token:csrf,student_id:row.data('student'),value:b.data('value'),grade_type:document.querySelector('#lessonGradeType')?.value||'lesson'}).done(()=>{state('Оценка '+b.data('value')+' сохранена ✓');location.reload()}).fail(()=>state('Ошибка сохранения оценки'))});});</script>
@endpush
